package main

import (
	"log/slog"
	"testing"
	"time"

	"github.com/voidrot/chorecast/server/internal/caltime"
	"github.com/voidrot/chorecast/server/internal/chores"
	"github.com/voidrot/chorecast/server/internal/clock"
	"github.com/voidrot/chorecast/server/internal/db"
	"github.com/voidrot/chorecast/server/internal/db/sqlc"
	"github.com/voidrot/chorecast/server/internal/household"
	"github.com/voidrot/chorecast/server/internal/kids"
	"github.com/voidrot/chorecast/server/internal/media"
	"github.com/voidrot/chorecast/server/internal/schedule"
)

// The horizon is regenerated by every trigger wired in newBackground: chore and kid changes,
// calendar changes, and the household day end.
func TestHorizonTriggers(t *testing.T) {
	store, err := db.Open(t.Context(), t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = store.Close() })
	// Wednesday 4 November 2026, 12:00 in Chicago.
	clk := clock.NewFake(time.Date(2026, 11, 4, 18, 0, 0, 0, time.UTC))
	runner, sched, bus := newBackground(store, clk, media.NewLocal(t.TempDir(), "", nil), slog.New(slog.DiscardHandler))

	// Before setup the day-end schedule has no calendar; ticking must not fail.
	if _, err := sched.Tick(t.Context()); err != nil {
		t.Fatalf("tick before setup: %v", err)
	}
	if err := store.CreateHousehold(t.Context(), sqlc.CreateHouseholdParams{
		Name: "Test", Timezone: "America/Chicago", DayEnd: "21:00", WeekStart: 0, CreatedAt: db.Timestamp(clk.Now()),
	}); err != nil {
		t.Fatal(err)
	}
	settle := func() {
		t.Helper()
		if _, err := bus.Dispatch(t.Context()); err != nil {
			t.Fatal(err)
		}
		if _, err := runner.RunDue(t.Context()); err != nil {
			t.Fatal(err)
		}
	}
	dates := func() (first, last string, n int) {
		t.Helper()
		rows, err := store.ListChoreInstancesFrom(t.Context(), "2000-01-01")
		if err != nil {
			t.Fatal(err)
		}
		if len(rows) == 0 {
			return "", "", 0
		}
		first, last = rows[0].OccurrenceDate, rows[0].OccurrenceDate
		for _, r := range rows {
			first, last = min(first, r.OccurrenceDate), max(last, r.OccurrenceDate)
		}
		return first, last, len(rows)
	}

	kidSvc := kids.NewService(store, clk, bus)
	if _, err := kidSvc.Create(t.Context(), kids.KidInput{DisplayName: "Sam", Color: "#2563eb"}); err != nil {
		t.Fatal(err)
	}
	start, _ := caltime.ParseDate("2026-11-01")
	if _, err := chores.New(store, clk, bus).Create(t.Context(), chores.ChoreInput{
		Name: "Dishes", Schedule: &schedule.ScheduleRule{Type: schedule.TypeDaily, StartDate: start},
	}); err != nil {
		t.Fatal(err)
	}
	settle()
	if first, last, n := dates(); n != 8 || first != "2026-11-04" || last != "2026-11-11" {
		t.Fatalf("after creating a chore: %d instances %s..%s, want 8 from today", n, first, last)
	}

	if _, err := kidSvc.Create(t.Context(), kids.KidInput{DisplayName: "Ada", Color: "#22c55e"}); err != nil {
		t.Fatal(err)
	}
	settle()
	if _, _, n := dates(); n != 16 {
		t.Fatalf("after adding a kid: %d instances, want 16", n)
	}

	// A later day end: in Berlin it's 22:00, so Wednesday is over there.
	hs := household.New(store, bus)
	settings, err := hs.Get(t.Context())
	if err != nil {
		t.Fatal(err)
	}
	clk.Set(time.Date(2026, 11, 4, 21, 0, 0, 0, time.UTC))
	settings.Timezone = "Europe/Berlin"
	if _, err := hs.Update(t.Context(), settings); err != nil {
		t.Fatal(err)
	}
	settle()
	if _, last, _ := dates(); last != "2026-11-12" {
		t.Fatalf("after the calendar change the horizon ends %s, want Berlin's today+7", last)
	}

	// The household day end moves the horizon forward a day.
	if _, err := sched.Tick(t.Context()); err != nil { // first tick starts the schedule
		t.Fatal(err)
	}
	clk.Set(time.Date(2026, 11, 5, 20, 0, 0, 0, time.UTC)) // Thursday 21:00 in Berlin
	if n, err := sched.Tick(t.Context()); err != nil || n == 0 {
		t.Fatalf("day-end tick enqueued %d jobs (err %v)", n, err)
	}
	settle()
	if _, last, _ := dates(); last != "2026-11-13" {
		t.Fatalf("after the day end the horizon ends %s, want 13 Nov", last)
	}
}
